def simulate_n(n):
    total_turns = 0
    for i in range(1 << n):
        state = [(i >> (n - 1 - j)) & 1 for j in range(n)]
        turns = 0
        while sum(state) > 0:
            k = sum(state)
            state[k-1] = 1 - state[k-1]
            turns += 1
        total_turns += turns
    return total_turns / (1 << n)

for n in range(1, 6):
    print(f"n={n}, avg={simulate_n(n)}")

